[theme='light'],
:root {
  --color-surface: var(--palette-gray-100);
  --color-surface-semihigh: var(--palette-gray-150);
  --color-surface-high: var(--palette-gray-200);
  --color-surface-higher: var(--palette-gray-250);
  --color-on-surface: var(--palette-gray-900);
  --color-on-surface-high: var(--palette-gray-900);
  --color-on-surface-low: var(--palette-gray-700);
  --color-sidebar: var(--palette-gray-250);
  --color-field: var(--palette-gray-200);
  --color-scrollbar-thumb: var(--palette-gray-400);
  --color-focus: color-mix(in oklab, var(--palette-accent) 20%, transparent);
}

[theme='dark'] {
  --color-surface: var(--palette-gray-900);
  --color-surface-semihigh: var(--palette-gray-800);
  --color-surface-high: var(--palette-gray-750);
  --color-surface-higher: var(--palette-gray-700);
  --color-on-surface: var(--palette-gray-100);
  --color-on-surface-high: var(--palette-gray-50);
  --color-on-surface-low: var(--palette-gray-300);
  --color-sidebar: var(--palette-gray-700);
  --color-field: var(--palette-gray-750);
  --color-scrollbar-thumb: var(--palette-gray-600);
  --color-hover: color-mix(in oklab, var(--palette-gray-600) 50%, transparent);
  --color-click: color-mix(in oklab, var(--palette-gray-600) 30%, transparent);
  --color-focus: color-mix(in oklab, var(--palette-accent) 50%, transparent);
}

:root {
  --focus-outline: 0 0 0 2px var(--color-focus) inset;
}

* {
  overflow: hidden;
}

.app {
  display: flex;
  height: 100dvh;
  font-family: var(--typeface-sans);
  font-size: var(--text-lg-font-size);
  line-height: var(--text-lg-line-height);
  background-color: var(--color-surface);
  color: var(--color-on-surface);
}

.sidebar {
  display: flex;
  flex-direction: column;
  width: var(--spacing-md);
  height: 100%;
  background-color: var(--color-sidebar);
}

.nav {
  .nav_new_thread {
    padding-inline: var(--spacing-2);
  }
}
.threads {
  flex-grow: 1;

  .threads_whitespace {
    height: var(--spacing-4);
  }
  .threads_thread,
  .threads_folder {
    display: flex;
    height: var(--spacing-8);
  }
  .threads_folder {
    color: var(--color-on-surface-high);
    font-weight: 600;
  }

  .threads_set_thread,
  .threads_toggle_folder {
    flex: 1;
    padding-inline: var(--spacing-2);
    white-space: nowrap;
    text-overflow: ellipsis;
  }
  .threads_toggle_folder {
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    &:focus-visible {
      box-shadow: var(--focus-outline);
    }
  }
  .threads_delete_thread {
    padding-inline: var(--spacing-2);
  }
}

.main {
  display: flex;
  flex: 1;
  flex-direction: column;
}
.status {
  display: flex;
  width: 100%;
  height: var(--spacing-8);
  flex-direction: column;
  justify-content: center;
  padding-inline: var(--spacing-2);
  background-color: var(--color-surface-semihigh);
  color: var(--color-on-surface-low);

  .status_folder {
    text-align: right;
  }
}
.page {
  flex: 1;

  & p {
    margin-block: var(--spacing-5);
  }
  & h1 {
    margin-top: 0;
    margin-bottom: var(--spacing-8);
    font-size: var(--text-4xl-font-size);
    line-height: var(--text-4xl-line-height);
    font-weight: 800;
  }
  & h2 {
    margin-top: var(--spacing-12);
    margin-bottom: var(--spacing-6);
    font-size: var(--text-2xl-font-size);
    line-height: var(--text-2xl-line-height);
    font-weight: 700;
  }
  & h3 {
    margin-top: var(--spacing-8);
    margin-bottom: var(--spacing-3);
    font-size: var(--text-xl-font-size);
    line-height: var(--text-xl-line-height);
    font-weight: 600;
  }
  & h4 {
    margin-top: 1.6875rem;
    margin-bottom: 0.5625rem;
    font-size: var(--text-lg-font-size);
    line-height: var(--text-lg-line-height);
    font-weight: 600;
  }
  & b,
  & strong {
    font-weight: 600;
  }
  & i,
  & em,
  & cite,
  & dfn,
  & address {
    font-style: italic;
  }
  & pre,
  & code {
    font-family: var(--typeface-mono);
  }

  & a,
  & summary {
    &:focus-visible {
      box-shadow: var(--focus-outline);
    }
  }
}

.message {
  display: flex;
  width: 100%;
  justify-content: center;
  padding-block: var(--spacing-4);

  &[role='user'],
  &[role='tool'] {
    background-color: var(--color-surface-semihigh);
  }
  .message_content {
    position: relative;
    width: var(--spacing-prose);
    padding-block: var(--spacing-4);

    &:hover .message_copy {
      opacity: 1;
    }
  }
  .message_prose_reasoning {
    color: var(--color-on-surface-low);
  }
  .message_copy {
    position: absolute;
    right: 0;
    bottom: 0;
    height: var(--spacing-8);
    padding-inline: var(--spacing-2);
    color: var(--color-on-surface-low);
    opacity: 0;

    &:focus-visible {
      opacity: 1;
    }
  }
}

.prompt {
  display: flex;
  width: 100%;
  height: 10rem;
  justify-content: center;
  background-color: var(--color-field);

  .prompt_field {
    width: var(--spacing-prose);
  }
  .prompt_textarea {
    padding-block: var(--spacing-8);
  }
}

.modal {
  position: fixed;
  inset: 0;
  display: flex;
  justify-content: center;
  pointer-events: none;

  &[position='center'] {
    align-items: center;
  }

  .modal_backdrop {
    position: fixed;
    inset: 0;
    pointer-events: none;
  }
  .modal_content {
    position: fixed;
    z-index: 800;
    width: var(--spacing-prose);
    background-color: var(--color-surface-high);
    pointer-events: auto;
  }
  .modal_search {
    display: flex;
    width: 100%;
    max-height: var(--spacing-sm);
    flex-direction: column;
  }
  .modal_search_query {
    width: 100%;
    height: var(--spacing-12);
    background-color: var(--color-surface-higher);
  }
  .modal_search_results {
    flex-grow: 1;
  }
  .modal_search_result {
    display: flex;
    width: 100%;
    height: var(--spacing-8);
    align-items: center;
    padding-inline: var(--spacing-8);

    &[focus] {
      background-color: var(--color-focus);
    }
  }
  .modal_search_result_label {
    flex-grow: 1;
    white-space: nowrap;
    text-overflow: ellipsis;
  }
  .modal_search_result_info {
    flex-shrink: 0;
    color: var(--color-on-surface-low);
    white-space: nowrap;
    text-overflow: ellipsis;
  }
}

.textarea {
  width: 100%;
  height: fit-content;
  border-radius: var(--rounded-md);
}

.input {
  width: 100%;
  height: 100%;
  padding: var(--spacing-4);
  border-radius: var(--rounded-md);
  font-size: var(--text-lg-font-size);
  line-height: var(--text-lg-line-height);
}

.scroll {
  position: relative;
  display: flex;
  flex: 1;

  .scroll_content {
    flex: 1;
    overflow: auto;

    > * {
      flex-shrink: 0;
    }

    /* use custom scrollbar */
    scrollbar-width: none;
    &::-webkit-scrollbar {
      display: none;
    }
  }
  .scroll_vertical_scrollbar {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    z-index: 100;
  }
  .scroll_vertical_track {
    width: 0.75rem;
    height: 100%;
    opacity: 0;
    transition-property: opacity;
    transition-duration: 0.5s;

    &[show] {
      opacity: 1;
    }
  }
  .scroll_vertical_thumb {
    width: 100%;
    background-color: var(--color-scrollbar-thumb);
  }
  .scroll_horizontal_scrollbar {
    position: absolute;
    right: 0;
    bottom: 0;
    left: 0;
    z-index: 100;
  }
  .scroll_horizontal_track {
    width: 100%;
    height: 0.75rem;
    opacity: 0;
    transition-property: opacity;
    transition-duration: 0.5s;

    &[show] {
      opacity: 1;
    }
  }
  .scroll_horizontal_thumb {
    height: 100%;
    background-color: var(--color-scrollbar-thumb);
  }
}

.button {
  &:hover {
    background-color: var(--color-hover);
  }
  &:active {
    background-color: var(--color-click);
  }
  &:focus-visible {
    box-shadow: var(--focus-outline);
  }
}

.checkbox {
  width: var(--spacing-4);
  height: var(--spacing-4);
  accent-color: var(--palette-accent);
}

.select {
  min-height: var(--spacing-8);
  padding-inline: var(--spacing-2);
  border-radius: var(--rounded-md);
  background-color: var(--color-field);
  color: var(--color-on-surface);
}

.radio_group_input,
.slider {
  accent-color: var(--palette-accent);
}

.switch {
  &:focus-visible {
    box-shadow: var(--focus-outline);
  }
}

import { scroll } from 'web/component/scroll'

type storybook_props = {
  components: Record<string, any>
}

export function storybook({ components }: storybook_props) {
  return h(
    'app',
    h(
      scroll,
      h(
        'storybook',
        h(
          'storybook_components',
          ...map(entries(components), ([name, component]) =>
            h(
              'storybook_component',
              {},
              h('storybook_component_name', {}, name),
              h('storybook_component_sample', {}, component),
            ),
          ),
        ),
      ),
    ),
  )
