export function Radio(props: radio) {
  const { value, set_value, options: flexible_items, placeholder = '', children } = props

  const items = Array.isArray(flexible_items) ?
    Object.fromEntries(map(flexible_items, item => [item, item])) :
    flexible_items

  return (
    <div className="radio">
      {
        map(items, ([id, name]) => {
          const checked = value == id

          return (
            <button className="item" {...p({ checked, onClick() { set_value(id) } })}>
              <span className="indicator">
                <span className="icon_radio">
                  {checked && (
                    <span className="icon_radio_checked"></span>
                  )}
                </span>
              </span>
              <span className="label" {...p({})}>{name}</span>
            </button>
          )
        })
      }
    </div>
  )
}

import { Button } from "./button";

type number_ = {
  value: number;
  set_value: (value: number | ((...args: any) => number)) => void;
};

export function Number({ value, set_value, ...props }: number_) {
  function handle_change(event: React.ChangeEvent<HTMLInputElement>) {
    set_value(+event.target.value);
  }

  function increase() {
    set_value((v: number) => v + 1)
  }

  function decrease() {
    set_value((v: number) => v - 1)
  }

  return (
    <div className="number" {...p({ ...props })}>
      <input {...p({ class: 'field', value, onchange: handle_change })}></input>
      <Button className="decrease" {...p({ onClick: decrease })}>
        <Icon {...p({ name: 'decrease' })}></Icon>
      </Button>
      <Button className="increase" {...p({ onClick: increase })}>
        <Icon {...p({ name: 'increase' })}></Icon>
      </Button>
    </div>
  );
}

