  width: var(--spacing-5);
  height: var(--spacing-5);
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--color-on-surface-low);
  border-radius: var(--rounded-sm);
  font-size: var(--text-sm-font-size);
  line-height: 1;
}

.switch {
  position: relative;
  display: inline-flex;
  width: var(--spacing-16);
  min-height: var(--spacing-8);
  align-items: center;
  justify-content: space-between;
  gap: var(--spacing-2);
  padding: var(--spacing-1) var(--spacing-2);
  border-radius: var(--rounded-full);
  background-color: var(--color-surface-higher);
  transition: background-color 150ms ease;

  &[aria-checked='true'] {
    background-color: var(--palette-accent);
    color: var(--palette-gray-50);
  }

  &:focus-visible {
    box-shadow: var(--focus-outline);
  }
}

.switch_thumb {
  width: var(--spacing-4);
  height: var(--spacing-4);
  flex: 0 0 auto;
  order: -1;
  border-radius: var(--rounded-full);
  background-color: currentColor;
}

.switch[aria-checked='true'] .switch_thumb {
  order: 1;
}

.select {
  position: relative;
  min-height: var(--spacing-8);
  color: var(--color-on-surface);
}

.select_trigger {
  display: flex;
  width: 100%;
  min-height: var(--spacing-8);
  align-items: center;
  justify-content: space-between;
  gap: var(--spacing-2);
  padding-inline: var(--spacing-2);
  border-radius: var(--rounded-md);
  background-color: var(--color-field);
  text-align: left;

  &:hover {
    background-color: var(--color-surface-higher);
  }
  &:focus-visible {
    box-shadow: var(--focus-outline);
  }
}

.select_label {
  flex: 1;
}

.select_icon {
  color: var(--color-on-surface-low);
}

.select_options {
  position: absolute;
  top: calc(100% + var(--spacing-1));
  right: 0;
  left: 0;
  z-index: 10;
  padding: var(--spacing-1);
  border-radius: var(--rounded-md);
  background-color: var(--color-surface-high);
  box-shadow: 0 2px 8px color-mix(in oklab, var(--color-on-surface) 20%, transparent);
}

.select_option {
  display: flex;
  width: 100%;
  min-height: var(--spacing-8);
  align-items: center;
  justify-content: space-between;
  gap: var(--spacing-2);
  padding-inline: var(--spacing-2);
  border-radius: var(--rounded-sm);
  text-align: left;

  &[aria-selected='true'],
  &:hover {
    background-color: var(--color-surface-higher);
  }
}

.select_option_check {
  color: var(--palette-accent);
}

.radio_group {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-2);
}

.radio_group_option {
  display: inline-flex;
  min-height: var(--spacing-8);
  align-items: center;
  gap: var(--spacing-2);
  padding-inline: var(--spacing-1);
  border-radius: var(--rounded-md);

  &:focus-visible {
    box-shadow: var(--focus-outline);
  }
}

.radio_group_indicator {
  display: inline-flex;
  width: var(--spacing-5);
  height: var(--spacing-5);
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--color-on-surface-low);
  border-radius: var(--rounded-full);
}

.radio_group_option[aria-checked='true'] .radio_group_indicator {
  border-color: var(--palette-accent);
}

.radio_group_dot {
  width: var(--spacing-2\.5);
  height: var(--spacing-2\.5);
  border-radius: var(--rounded-full);
  background-color: var(--palette-accent);
}

.slider {
  position: relative;
  display: flex;
  width: var(--spacing-3xl);
  height: var(--spacing-8);
  align-items: center;
  padding-inline: var(--spacing-2);
  border-radius: var(--rounded-md);
  touch-action: none;
  cursor: pointer;

  &:focus-visible {
    box-shadow: var(--focus-outline);
  }
}

.slider_track {
  position: absolute;
  right: var(--spacing-2);
  left: var(--spacing-2);
  height: var(--spacing-1);
  border-radius: var(--rounded-full);
  background: linear-gradient(
    to right,
    var(--palette-accent) var(--slider-value),
    var(--color-surface-higher) var(--slider-value)
  );
}

.slider_thumb {
  position: absolute;
  left: var(--slider-value);
  width: var(--spacing-4);
  height: var(--spacing-4);
  border: 2px solid var(--palette-accent);
  border-radius: var(--rounded-full);
  background-color: var(--color-surface);
  transform: translateX(-50%);
}

import { button } from 'web/component/button'
import { checkbox } from 'web/component/checkbox'
import { input } from 'web/component/input'
import { radio_group } from 'web/component/radio_group'
import { select } from 'web/component/select'
import { slider } from 'web/component/slider'
import { switch_toggle } from 'web/component/switch'
import { textarea } from 'web/component/textarea'

import { storybook } from './storybook'

const options = [
  { value: 'one', label: 'One' },
  { value: 'two', label: 'Two' },
  { value: 'three', label: 'Three' },
]

export function app() {
  use_sync_theme('system')
  use_window_active()

  const [input_value, set_input_value] = use_state('')
  const [textarea_value, set_textarea_value] = use_state('')
  const [checkbox_checked, set_checkbox_checked] = use_state(false)
  const [switch_checked, set_switch_checked] = use_state(false)
  const [select_value, set_select_value] = use_state('one')
  const [radio_value, set_radio_value] = use_state('one')
  const [slider_value, set_slider_value] = use_state(50)

  const components = {
    button: h(button, { children: 'Button' }),
    input: h(input, {
      value: input_value,
      set_value: set_input_value,
      placeholder: 'Type something',
    }),
    textarea: h(textarea, {
      value: textarea_value,
      set_value: set_textarea_value,
      placeholder: 'Write a message',
    }),
    checkbox: h(checkbox, {
      checked: checkbox_checked,
      set_checked: set_checkbox_checked,
    }),
    switch: h(switch_toggle, {
      checked: switch_checked,
      set_checked: set_switch_checked,
      children: 'Enable feature',
    }),
    select: h(select, {
      value: select_value,
      set_value: set_select_value,
      options,
    }),
    radio_group: h(radio_group, {
      value: radio_value,
      set_value: set_radio_value,
      options,
    }),
    slider: h(slider, {
      value: slider_value,
      set_value: set_slider_value,
    }),
  }

  return h(storybook, { components })
}

