type storybook_props = {
  components: Record<string, any>
}

export function storybook({ components }: storybook_props) {
  return h(
    'main.storybook',
    h(
      'div.storybook_components',
      ...map(entries(components), ([name, component]) =>
        h(
          'section.storybook_component',
          {},
          h('h2.storybook_component_name', {}, name),
          h('div.storybook_component_sample', {}, component),
        ),
      ),
    ),
  )
}

content.text:
type select_option = {
  value: string
  label: string
}

type select_props = {
  value: string
  set_value: (value: string) => void
  options: select_option[]
  [key: Key]: any
}

export function select({ value, set_value, options, ...props }: select_props) {
  const [open, set_open] = use_state(false)
  const selected_option = options.find((option) => option.value === value)

  function handle_toggle() {
    set_open(!open)
  }

  function handle_select(option_value: string) {
    set_value(option_value)
    set_open(false)
  }

  return h(
    'div.select',
    props,
    h(
      'button.select_trigger',
      {
        type: 'button',
        'aria-haspopup': 'listbox',
        'aria-expanded': open,
        'aria-label': props['aria-label'],
        onclick: handle_toggle,
      },
      h('span.select_label', {}, selected_option?.label ?? ''),
      h('span.select_icon', {}, '⌄'),
    ),
    open
      ? h(
          'div.select_options',
          { role: 'listbox' },
          ...map(options, (option) =>
            h(
              'button.select_option',
              {
                type: 'button',
                role: 'option',
                'aria-selected': option.value === value,
                onclick: () => handle_select(option.value),
              },
              h('span.select_option_label', {}, option.label),
              option.value === value ? h('span.select_option_check', {}, '✓') : null,
            ),
          ),
        )
      : null,
  )
}

type slider_props = {
  value: number
  set_value: (value: number) => void
  min?: number
  max?: number
  step?: number
  [key: Key]: any
}

export function slider({
  value,
  set_value,
  min = 0,
  max = 100,
  step = 1,
  ...props
}: slider_props) {
  const range = max - min
  const ratio = range > 0 ? Math.min(1, Math.max(0, (value - min) / range)) : 0

  function set_from_ratio(next_ratio: number) {
    const safe_step = step > 0 ? step : 1
    const raw_value = min + Math.min(1, Math.max(0, next_ratio)) * range
    const stepped_value = min + Math.round((raw_value - min) / safe_step) * safe_step
    set_value(Number(Math.min(max, Math.max(min, stepped_value)).toFixed(6)))
  }

  function handle_pointer(event) {
    const bounds = event.currentTarget.getBoundingClientRect()
    if (bounds.width > 0) {
      set_from_ratio((event.clientX - bounds.left) / bounds.width)
    }
  }

  function handle_keydown(event) {
    const safe_step = step > 0 ? step : 1
    if (event.key === 'ArrowRight' || event.key === 'ArrowUp') {
      event.preventDefault()
      set_value(Math.min(max, value + safe_step))
    } else if (event.key === 'ArrowLeft' || event.key === 'ArrowDown') {
      event.preventDefault()
      set_value(Math.max(min, value - safe_step))
    } else if (event.key === 'Home') {
      event.preventDefault()
      set_value(min)
    } else if (event.key === 'End') {
      event.preventDefault()
      set_value(max)
    }
  }

  return h(
    'button.slider',
    {
      ...props,
      type: 'button',
      role: 'slider',
      'aria-valuemin': min,
      'aria-valuemax': max,
      'aria-valuenow': value,
      onpointerdown: handle_pointer,
      onpointermove: (event) => {
        if (event.buttons) handle_pointer(event)
      },
      onkeydown: handle_keydown,
      style: { '--slider-value': `${ratio * 100}%`, ...props.style },
    },
    h('span.slider_track', {}),
    h('span.slider_thumb', {}),
  )
}

  .scroll_horizontal_track {
    width: 100%;
    height: 0.75rem;
    opacity: 0;
    transition-property: opacity;
    transition-duration: 0.5s;

    &[show] {
      opacity: 1;
    }
  }
  .scroll_horizontal_thumb {
    height: 100%;
    background-color: var(--color-scrollbar-thumb);
  }
}

.button {
  display: inline-flex;
  min-height: var(--spacing-8);
  align-items: center;
  justify-content: center;
  gap: var(--spacing-2);
  padding-inline: var(--spacing-2);
  border-radius: var(--rounded-md);

  &:hover {
    background-color: var(--color-hover);
  }
  &:active {
    background-color: var(--color-click);
  }
  &:focus-visible {
    box-shadow: var(--focus-outline);
  }
}

.input,
.select {
  width: 100%;
  max-width: var(--spacing-3xl);
}

.textarea {
  width: 100%;
  max-width: var(--spacing-3xl);
  min-height: var(--spacing-12);
  padding: var(--spacing-2);
  border-radius: var(--rounded-md);
  background-color: var(--color-field);
  color: var(--color-on-surface);

  &::placeholder {
    color: var(--color-on-surface-low);
  }
}

.input {
  height: auto;
  min-height: var(--spacing-8);
  padding-inline: var(--spacing-2);
  border-radius: var(--rounded-md);
  background-color: var(--color-field);
  color: var(--color-on-surface);
  font-size: var(--text-base-font-size);
  line-height: var(--text-base-line-height);

  &::placeholder {
    color: var(--color-on-surface-low);
  }
}

.checkbox {
  display: inline-flex;
  min-height: var(--spacing-8);
  align-items: center;
  gap: var(--spacing-2);
  padding-inline: var(--spacing-1);
  border-radius: var(--rounded-md);

  &[aria-checked='true'] .checkbox_indicator {
    border-color: var(--palette-accent);
    background-color: var(--palette-accent);
    color: var(--palette-gray-50);
  }

  &:focus-visible {
    box-shadow: var(--focus-outline);
  }
}

.checkbox_indicator {
  display: inline-flex;
  width: var(--spacing-5);
  height: var(--spacing-5);
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--color-on-surface-low);
  border-radius: var(--rounded-sm);
  font-size: var(--text-sm-font-size);
  line-height: 1;
}

.switch {
  position: relative;
  display: inline-flex;
  width: max-content;
  min-height: var(--spacing-8);
  align-items: center;
  justify-content: space-between;
  gap: var(--spacing-2);
  padding: var(--spacing-1) var(--spacing-2);
  border-radius: var(--rounded-full);
  background-color: var(--color-surface-higher);
  transition: background-color 150ms ease;

  &[aria-checked='true'] {
    background-color: var(--palette-accent);
    color: var(--palette-gray-50);
  }

  &:focus-visible {
    box-shadow: var(--focus-outline);
  }
}

.switch_thumb {
  width: var(--spacing-4);
  height: var(--spacing-4);
  flex: 0 0 auto;
  order: -1;
  border-radius: var(--rounded-full);
  background-color: currentColor;
}

.switch[aria-checked='true'] .switch_thumb {
  order: 1;
}

.select {
  position: relative;
  min-height: var(--spacing-8);
  overflow: visible;
  color: var(--color-on-surface);
}

.select_trigger {
  display: flex;
  width: 100%;
  min-height: var(--spacing-8);
  align-items: center;
  justify-content: space-between;
  gap: var(--spacing-2);
  padding-inline: var(--spacing-2);
  border-radius: var(--rounded-md);
  background-color: var(--color-field);
  text-align: left;

  &:hover {
    background-color: var(--color-surface-higher);
  }
  &:focus-visible {
    box-shadow: var(--focus-outline);
  }
}

.select_label {
  flex: 1;
}

.select_icon {
  color: var(--color-on-surface-low);
}

.select_options {
  position: absolute;
  top: calc(100% + var(--spacing-1));
  right: 0;
  left: 0;
  z-index: 10;
  padding: var(--spacing-1);
  border-radius: var(--rounded-md);
  background-color: var(--color-surface-high);
  box-shadow: 0 2px 8px color-mix(in oklab, var(--color-on-surface) 20%, transparent);
}

.select_option {
  display: flex;
  width: 100%;
  min-height: var(--spacing-8);
  align-items: center;
  justify-content: space-between;
  gap: var(--spacing-2);
  padding-inline: var(--spacing-2);
  border-radius: var(--rounded-sm);
  text-align: left;

  &[aria-selected='true'],
  &:hover {
    background-color: var(--color-surface-higher);
  }
}

.select_option_check {
  color: var(--palette-accent);
}

.radio_group {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-2);
}

.radio_group_option {
  display: inline-flex;
  min-height: var(--spacing-8);
  align-items: center;
  gap: var(--spacing-2);
  padding-inline: var(--spacing-1);
  border-radius: var(--rounded-md);

  &:focus-visible {
    box-shadow: var(--focus-outline);
  }
}

.radio_group_indicator {
  display: inline-flex;
  width: var(--spacing-5);
  height: var(--spacing-5);
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--color-on-surface-low);
  border-radius: var(--rounded-full);
}

.radio_group_option[aria-checked='true'] .radio_group_indicator {
  border-color: var(--palette-accent);
}

.radio_group_dot {
  width: var(--spacing-2\.5);
  height: var(--spacing-2\.5);
  border-radius: var(--rounded-full);
  background-color: var(--palette-accent);
}

.slider {
  position: relative;
  display: flex;
  width: min(var(--spacing-3xl), 100%);
  height: var(--spacing-8);
  align-items: center;
  padding-inline: var(--spacing-2);
  border-radius: var(--rounded-md);
  touch-action: none;
  cursor: pointer;

  &:focus-visible {
    box-shadow: var(--focus-outline);
  }
}

.slider_track {
  position: absolute;
  right: var(--spacing-2);
  left: var(--spacing-2);
  height: var(--spacing-1);
  border-radius: var(--rounded-full);
  background: linear-gradient(
    to right,
    var(--palette-accent) var(--slider-value),
    var(--color-surface-higher) var(--slider-value)
  );
}

.slider_thumb {
  position: absolute;
  left: var(--slider-value);
  width: var(--spacing-4);
  height: var(--spacing-4);
  border: 2px solid var(--palette-accent);
  border-radius: var(--rounded-full);
  background-color: var(--color-surface);
  transform: translateX(-50%);
}

type storybook_props = {
  components: Record<string, any>
}

export function storybook({ components }: storybook_props) {
  return h(
    'main.storybook',
    h(
      'div.storybook_components',
      ...map(entries(components), ([name, component]) =>
        h(
          'section.storybook_component',
          {},
          h('h2.storybook_component_name', {}, name),
          h('div.storybook_component_sample', {}, component),
        ),
      ),
    ),
  )
}

